    "version": "v0.9",
    "updateComponents": {
      "surfaceId": "tokyo-itinerary-surface",
      "components": [
        {
          "id": "root",
          "component": "Column",
          "children": [
            "title_text",
            "intro_text_1",
            "total_budget_card",
            "divider_1",
